def boostedHIndex(citations, k):
    c = sorted(citations, reverse=True)
    n = len(c)

    def cost(h):
        total = 0
        for i in range(h):
            if c[i] < h:
                total += h - c[i]
        return total

    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if cost(mid) <= k:
            lo = mid
        else:
            hi = mid - 1
    return lo
